/*
 * GPS NEO-6M/8M Tracker — ESP32 + OLED + Buzzer
 *
 * Hardware:
 *   NEO-6M/8M GPS:
 *     VCC -> 3.3V   GND -> GND
 *     TX  -> GPIO16 (RX2)   RX  -> GPIO17 (TX2)
 *   SSD1306 OLED (I2C):
 *     VCC -> 3.3V   GND -> GND
 *     SCL -> GPIO22 (I2C SCL)   SDA -> GPIO21 (I2C SDA)
 *   Green LED (Fix OK):  D2 -> Anode, Cathode -> GND
 *   Red LED (No Fix):    D4 -> Anode, Cathode -> GND
 *   Buzzer (Fix Alert):  D5 -> +, - -> GND
 *
 * Displays: Lat, Lng, Alt, Sats, Speed, Time on OLED.
 * Green LED blinks on fix, red LED on when no fix,
 * buzzer beeps once when fix is first acquired.
 */

#include <TinyGPS++.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// OLED config
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// GPS
TinyGPSPlus gps;

// Pins
const int GREEN_LED = 2;
const int RED_LED   = 4;
const int BUZZER    = 5;

// State
bool greenState = false;
bool redState   = true;
bool fixWasAcquired = false;
unsigned long lastBlink  = 0;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(9600);
  Serial2.begin(9600, SERIAL_8N1, 16, 17);

  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);

  digitalWrite(GREEN_LED, LOW);
  digitalWrite(RED_LED, HIGH);   // Red ON = no fix
  digitalWrite(BUZZER, LOW);

  // Init OLED
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("GPS NEO-6M/8M");
  display.println("Waiting for");
  display.println("satellites...");
  display.display();

  Serial.println("========================================");
  Serial.println("  GPS NEO-6M/8M Tracker");
  Serial.println("  OLED + Dual LED + Buzzer");
  Serial.println("========================================");
  Serial.println();
}

void loop() {
  // Feed GPS data
  while (Serial2.available() > 0) {
    gps.encode(Serial2.read());
  }

  static unsigned long lastOled = 0;
  if (millis() - lastOled >= 1000) {
    lastOled = millis();

    if (gps.location.isValid()) {
      // --- FIX ACQUIRED ---

      // Buzzer: beep once on first fix
      if (!fixWasAcquired) {
        fixWasAcquired = true;
        digitalWrite(BUZZER, HIGH);
        delay(100);
        digitalWrite(BUZZER, LOW);
        delay(100);
        digitalWrite(BUZZER, HIGH);
        delay(100);
        digitalWrite(BUZZER, LOW);
      }

      // Green LED blink, Red LED off
      digitalWrite(RED_LED, LOW);
      greenState = !greenState;
      digitalWrite(GREEN_LED, greenState ? HIGH : LOW);

      // Serial output
      Serial.println("--- GPS Fix Acquired ---");
      Serial.print("Latitude:    ");
      Serial.print(gps.location.lat(), 6);
      Serial.println(" deg");
      Serial.print("Longitude:   ");
      Serial.print(gps.location.lng(), 6);
      Serial.println(" deg");
      if (gps.altitude.isValid()) {
        Serial.print("Altitude:    ");
        Serial.print(gps.altitude.meters(), 1);
        Serial.print(" m  (");
        Serial.print(gps.altitude.feet(), 1);
        Serial.println(" ft)");
      }
      if (gps.satellites.isValid()) {
        Serial.print("Satellites:  ");
        Serial.println(gps.satellites.value());
      }
      if (gps.speed.isValid()) {
        Serial.print("Speed:       ");
        Serial.print(gps.speed.kmph(), 1);
        Serial.println(" km/h");
      }
      if (gps.time.isValid()) {
        Serial.print("Time (UTC):  ");
        if (gps.time.hour() < 10) Serial.print('0');
        Serial.print(gps.time.hour());
        Serial.print(':');
        if (gps.time.minute() < 10) Serial.print('0');
        Serial.print(gps.time.minute());
        Serial.print(':');
        if (gps.time.second() < 10) Serial.print('0');
        Serial.println(gps.time.second());
      }
      Serial.println();

      // --- OLED Display ---
      display.clearDisplay();
      display.setTextSize(1);
      display.setTextColor(SSD1306_WHITE);

      // Header
      display.setCursor(0, 0);
      display.println("== GPS FIX ACQUIRED ==");

      // Latitude
      display.setCursor(0, 12);
      display.print("LAT:");
      display.println(gps.location.lat(), 6);

      // Longitude
      display.setCursor(0, 22);
      display.print("LNG:");
      display.println(gps.location.lng(), 6);

      // Altitude
      if (gps.altitude.isValid()) {
        display.setCursor(0, 32);
        display.print("ALT:");
        display.print(gps.altitude.meters(), 1);
        display.println("m");
      }

      // Speed & Sats
      display.setCursor(0, 42);
      if (gps.speed.isValid()) {
        display.print("SPD:");
        display.print(gps.speed.kmph(), 1);
        display.print("km/h ");
      }
      if (gps.satellites.isValid()) {
        display.print("SAT:");
        display.println(gps.satellites.value());
      }

      // Time
      if (gps.time.isValid()) {
        display.setCursor(0, 54);
        display.print("UTC ");
        if (gps.time.hour() < 10) display.print('0');
        display.print(gps.time.hour());
        display.print(':');
        if (gps.time.minute() < 10) display.print('0');
        display.print(gps.time.minute());
        display.print(':');
        if (gps.time.second() < 10) display.print('0');
        display.print(gps.time.second());
      }

      display.display();

    } else {
      // --- NO FIX ---
      digitalWrite(RED_LED, HIGH);  // Red ON = searching
      digitalWrite(GREEN_LED, LOW);

      // OLED: waiting screen
      display.clearDisplay();
      display.setTextSize(1);
      display.setTextColor(SSD1306_WHITE);
      display.setCursor(0, 0);
      display.println("  GPS searching...");
      display.setCursor(0, 16);
      display.print("Chars: ");
      display.println(gps.charsProcessed());
      display.setCursor(0, 28);
      display.print("Pass:  ");
      display.println(gps.passedChecksum());
      display.setCursor(0, 40);
      display.print("Fail:  ");
      display.println(gps.failedChecksum());
      display.display();

      Serial.print(".");
    }
  }
}
